, \"id_email\" as \"id_email\", id_phone as \"identity\", id_name, customer_category as \"CUSTOMER_CATEGORY2\", recency_score as \"Last_purchased_days\", frequency_score as \"GROSS_ORDERS\", monetary_score as \"Total_revenue\", PINCODE as \"Pincode\", DISTRICT as \"District\", STATE as \"State_Name\", last_name as \"Last Name\", DATEDIFF(\'day\', FIRST_ORDER_DATE, CURRENT_DATE) AS \"DAYS_SINCE_FIRST_ORDER\", LAST_1_MONTH_ORDERS as \"LAST_1_MONTH_ORDERS\", LAST_3_MONTHS_ORDERS as \"LAST_3_MONTHS_ORDERS\", LAST_6_MONTHS_ORDERS as \"LAST_6_MONTHS_ORDERS\", LAST_12_MONTHS_ORDERS as \"LAST_12_MONTHS_ORDERS\", AVERAGE_TIME_DURATION_BETWEEN_PURCHASE as \"AVERAGE_TIME_DURATION_BETWEEN_PURCHASE\", TIME_BETWEEN_1_AND_2_ORDER as \"TIME_BETWEEN_1_AND_2_ORDER\", TIME_BETWEEN_2_AND_3_ORDER as \"TIME_BETWEEN_2_AND_3_ORDER\", NET_ITEMS as \"Net_units\", GROSS_REVENUE as \"GROSS_REVENUE\", aov as \"GROSS_AOV\", RETURN_PERCENTAGE as \"Return_percentage\", DISCOUNT_PERCENTAGE as \"Discount%\", CANCEL_PERCENTAGE as \"Cancel_percentage\", GROSS_DISCOUNT as \"Total_discount\", RECOMMEND_SIZE as \"RECOMMEND_SIZE\", COD_PERCENTAGE AS \"COD_PERCENTAGE\", PREPAID_PERCENTAGE AS \"PREPAID_PERCENTAGE\", FREQUENTLY_PURCHASED_CATEGORY AS \"FREQUENTLY_PURCHASED_CATEGORY\", FREQUENTLY_PURCHASED_SKU_GROUP AS \"FREQUENTLY_PURCHASED_SKU_GROUP\", AVERAGE_SELLING_PRICE AS \"AVERAGE_SELLING_PRICE\", customer_channel AS \"CUSTOMER_CHANNEL\", channel AS \"CHANNEL\", FIRST_PURCHASED_CATEGORIES AS \"FIRST_PURCHASED_CATEGORIES\" from categorized_data where length(id_phone) = 13 ), main_data3 as ( select timeline, \"identity\", \"id_email\", id_name as \"id_name\", \"CUSTOMER_CATEGORY2\", \"Last_purchased_days\", \"GROSS_ORDERS\", \"Total_revenue\", \"Pincode\", \"District\", \"State_Name\", \"Last Name\", \"DAYS_SINCE_FIRST_ORDER\", \"LAST_1_MONTH_ORDERS\", \"LAST_3_MONTHS_ORDERS\", \"LAST_6_MONTHS_ORDERS\", \"LAST_12_MONTHS_ORDERS\", \"AVERAGE_TIME_DURATION_BETWEEN_PURCHASE\", \"TIME_BETWEEN_1_AND_2_ORDER\",